1: import {
2:   LAYERS, ZONES, ORES, ORE_ORDER, STIM_MAX, PERKS, ATTRIBUTES, OUTFITS,
3:   MINING_TOOLS, COMBAT_WEAPONS, GEAR_SLOTS, MAX_INVENTORY, RARITIES,
4:   fmt, costLabel, canAfford, spend, makeEnemy, playerStats,
5:   playerAttackInterval, layerMaxHp, strikeYield, pickPower, miningTool, combatWeapon, toolCooldown,
6:   drillRate, salvageCapsRate, overloadGain, xpNeeded, xpMultiplier, outfitCost, outfitLevel,
7:   attrLevel, perkRank, pickaxeCost, crewCost, drillCost,
8:   weaponCost, armorCost, stimCost, makeLootItem, lootRunCost, gearStats, gearScore,
9:   gearStatLines, rarityOf, scrapValue, equippedItem,
10: } from './data.js';
11: import { loadState, persist, wipeSave, offlineReport, resetProgress, formatGainList } from './state.js';
12: import { GameAudio } from './audio.js';
13: import { MineRenderer, CombatRenderer } from './render.js';
14: import { UI } from './ui.js';
15: 
16: const $ = (id) => document.getElementById(id);
17: 
18: class Game {
19:   constructor() {
20:     const loaded = loadState();
21:     this.state = loaded.state;
22:     this.fresh = loaded.fresh;
23:     this.logs = [];
24:     this.audio = new GameAudio(this.state.sound);
25:     this.nextSpawn = 0;
26:     this.lastStrike = 0;
27:     this.lastTick = performance.now();
28:     this.lastUI = 0;
29:     this.lastSave = performance.now();
30: 
31:     const offline = offlineReport(this.state);
32:     this.setupEnemy(performance.now());
33: 
34:     this.mineRenderer = new MineRenderer($('mineCanvas'), this);
35:     this.combatRenderer = new CombatRenderer($('combatCanvas'), this);
36:     this.ui = new UI(this);
37:     this.ui.updateSoundButton();
38: 
39:     this.seedLog();
40:     if (offline) this.showOffline(offline);
41:     else if (this.fresh) {
42:       this.log('Rig online. Strike the vein and rebuild. The wastes are listening.', 'good');
43:     } else {
44:       this.log('Rig restored from last session.', 'good');
45:     }
46: 
47:     this.bindGlobal();
48:     this.tick = this.tick.bind(this);
49:     setInterval(() => this.tick(performance.now()), 100);
50:     setInterval(() => this.ui.render(), 150);
51:     this.saveNow();
52:   }
53: 
54:   setupEnemy(now) {
55:     const c = this.state.combat;
56:     if (!c.enemy || !c.enemy.hp || c.enemy.hp <= 0) {
57:       const wave = c.waves[c.zone] || 1;
58:       c.enemy = makeEnemy(c.zone, wave);
59:     }
60:     c.enemy.nextAttack = now + c.enemy.interval * 0.9;
61:     c.nextPlayerAttack = 0;
62:     const stats = playerStats(this.state);
63:     c.hp = Math.min(stats.maxHp, Math.max(1, c.hp || stats.maxHp));
64:     if (c.hp <= 0) {
65:       c.hp = stats.maxHp;
66:       c.deadUntil = 0;
67:     }
68:   }
69: 
70:   seedLog() {}
71: 
72:   bindGlobal() {
73:     document.getElementById('modal').addEventListener('click', (e) => {
74:       if (e.target.id === 'modal') this.ui.closeModal();
75:     });
76:     document.addEventListener('keydown', (e) => {
77:       if (e.key === 'Escape') this.ui.closeModal();
78:     });
79:     window.addEventListener('pagehide', () => this.saveNow());
80:     document.addEventListener('visibilitychange', () => {
81:       if (document.hidden) this.saveNow();
82:       else this.lastTick = performance.now();
83:     });
84:   }
85: 
86:   tick(now) {
87:     const dt = Math.min(1.5, Math.max(0, (now - this.lastTick) / 1000));
88:     this.lastTick = now;
89:     this.passiveGain(dt);
90:     this.tickMining(now);
91:     this.tickCombat(now, dt);
92:     if (now - this.lastUI > 150) {
93:       this.ui.render();
94:       this.lastUI = now;
95:     }
96:     if (now - this.lastSave > 5000) {
97:       this.saveNow();
98:       this.lastSave = now;
99:     }
100:   }
101: 
102:   passiveGain(dt) {
103:     const s = this.state;
104:     for (let i = 0; i < LAYERS.length; i++) {
105:       const count = s.drills[i] || 0;
106:       if (!count) continue;
107:       const ore = LAYERS[i].ore;
108:       const amount = count * drillRate(s, i) * dt;
109:       s.ores[ore] += amount;
110:       s.stats.totalMined += amount;
111:     }
112:     const caps = salvageCapsRate(s) * dt;
113:     if (caps > 0) {
114:       s.caps += caps;
115:       s.stats.totalCaps = (s.stats.totalCaps || 0) + caps;
116:     }
117:   }
118: 
119:   /* ── mining ──────────────────────────────────────────────── */
120:   tickMining(now) {
121:     const s = this.state;
122:     if (!s.autoMine) return;
123:     if (now - this.lastStrike >= toolCooldown(s)) this.strikeMine(true, now);
124:   }
125: 
126:   toggleAutoMine() {
127:     const s = this.state;
128:     s.autoMine = !s.autoMine;
129:     this.audio.tone({ freq: s.autoMine ? 420 : 240, dur: 0.08, type: 'triangle', vol: 0.16 });
130:     this.ui.toast(s.autoMine ? 'AUTO-MINE ENGAGED — the rig swings itself' : 'AUTO-MINE DISENGAGED', s.autoMine ? 'good' : '');
131:     this.log(`Auto-mining ${s.autoMine ? 'engaged' : 'disengaged'}.`, '');
132:     if (s.autoMine) this.strikeMine(true);
133:     this.ui.render();
134:     this.saveNow();
135:   }
136: 
137:   strikeMine(auto = false, now = performance.now()) {
138:     const s = this.state;
139:     const tool = miningTool(s);
140:     const cooldown = toolCooldown(s);
141:     if (now - this.lastStrike < cooldown) return;
142:     this.lastStrike = now;
143:     const i = s.layer;
144:     const layer = LAYERS[i];
145:     const yieldAmt = strikeYield(s, i);
146:     const crit = Math.random() < 0.07 + tool.critBonus;
147:     const gained = yieldAmt * (crit ? 3 : 1);
148:     s.ores[layer.ore] += gained;
149:     s.stats.totalMined += gained;
150:     s.stats.clicks = (s.stats.clicks || 0) + 1;
151: 
152:     const dmg = pickPower(s);
153:     const maxHp = layerMaxHp(s, i);
154:     s.veinHp[i] = (s.veinHp[i] ?? maxHp) - dmg;
155:     let broke = false;
156:     if (s.veinHp[i] <= 0) {
157:       broke = true;
158:       const bonus = yieldAmt * 10;
159:       s.ores[layer.ore] += bonus;
160:       s.stats.totalMined += bonus;
161:       s.nodes[i] = (s.nodes[i] || 0) + 1;
162:       s.veinHp[i] = layerMaxHp(s, i);
163:       this.mineRenderer.veinBreak();
164:       if (!auto) {
165:         this.audio.shatter();
166:         this.log(`Vein shattered. Richness ×${(1 + 0.04 * s.nodes[i]).toFixed(2)} · +${fmt(bonus)} ${ORES[layer.ore].name}.`, 'good');
167:       }
168:     } else if (!auto || Math.random() < 0.35) {
169:       this.audio[crit ? 'crit' : 'strike']();
170:     }
171:     this.mineRenderer.strike();
172:     if (!auto || broke || crit) this.mineRenderer.floatOre(Math.round(gained), layer.ore, crit);
173:     if (broke && !auto) {
174:       this.mineRenderer.floatOre(Math.round(yieldAmt * 10), layer.ore, true);
175:       this.ui.toast(`VEIN SHATTERED · +${fmt(Math.round(yieldAmt * 10))} ${ORES[layer.ore].name}`, 'good');
176:     } else if (crit && !auto) {
177:       this.ui.toast(`CRITICAL SEAM · +${fmt(Math.round(gained))} ${ORES[layer.ore].name}`, 'good');
178:     }
179:     if ((s.stats.clicks || 0) === 1) {
180:       this.log('First swing. Keep the tool moving — the vein gives more the deeper you go.', 'good');
181:     }
182:     this.gainXp(1 + (broke ? 12 + i * 2 : 0));
183:     if (!auto) this.ui.render();
184:   }
185: 
186:   /* ── RPG progression ─────────────────────────────────────── */
187:   gainXp(amount) {
188:     const s = this.state;
189:     const mult = xpMultiplier(s);
190:     s.xp = (s.xp || 0) + Math.max(0, amount) * mult;
191:     let levels = 0;
192:     let perks = 0;
193:     let guard = 0;
194:     while (s.xp >= xpNeeded(s.level || 1) && guard++ < 100) {
195:       s.xp -= xpNeeded(s.level || 1);
196:       s.level = (s.level || 1) + 1;
197:       s.points = (s.points || 0) + 3;
198:       levels += 1;
199:       if (s.level % 3 === 0) {
200:         s.perkPoints = (s.perkPoints || 0) + 1;
201:         perks += 1;
202:       }
203:     }
204:     if (levels > 0) {
205:       const stats = playerStats(s);
206:       s.combat.hp = stats.maxHp;
207:       this.audio.levelUp();
208:       this.combatRenderer.levelUp();
209:       const perkText = perks > 0 ? ` · +${perks} PERK CHOICE${perks > 1 ? 'S' : ''}` : '';
210:       this.ui.toast(`LEVEL ${s.level} · +${levels * 3} ATTRIBUTE POINTS${perkText}`, 'lore');
211:       this.log(`Survivor reached level ${s.level}. +${levels * 3} attribute points${perks > 0 ? ' and a perk choice' : ''}.`, 'good');
212:       this.ui.render();
213:       this.saveNow();
214:     }
215:   }
216: 
217:   spendPoint(id) {
218:     const s = this.state;
219:     const attr = ATTRIBUTES.find((a) => a.id === id);
220:     if (!attr) return;
221:     if ((s.points || 0) < 1) {
222:       this.ui.toast('No attribute points — level up to earn more.', 'bad');
223:       this.audio.error();
224:       return;
225:     }
226:     s.attributes[id] = attrLevel(s, id) + 1;
227:     s.points -= 1;
228:     const stats = playerStats(s);
229:     s.combat.hp = Math.min(stats.maxHp, s.combat.hp + (id === 'vit' ? 8 : 0));
230:     this.audio.tone({ freq: 440, end: 620, dur: 0.09, type: 'triangle', vol: 0.17 });
231:     this.ui.render();
232:     this.saveNow();
233:   }
234: 
235:   respec() {
236:     const s = this.state;
237:     const spent = ATTRIBUTES.reduce((sum, a) => sum + attrLevel(s, a.id), 0);
238:     if (spent === 0) {
239:       this.ui.toast('No attribute points to refund.', 'bad');
240:       return;
241:     }
242:     const cost = 100 + spent * 10;
243:     if (s.caps < cost) {
244:       this.audio.error();
245:       this.ui.toast(`Respec costs ${fmt(cost)} caps (money).`, 'bad');
246:       return;
247:     }
248:     s.caps -= cost;
249:     s.points = (s.points || 0) + spent;
250:     s.attributes = { str: 0, vit: 0, agi: 0, luk: 0 };
251:     const stats = playerStats(s);
252:     s.combat.hp = Math.min(stats.maxHp, s.combat.hp);
253:     this.audio.buy();
254:     this.ui.toast(`Attributes reset · ${spent} points refunded · −${fmt(cost)} caps`, 'good');
255:     this.log(`Paid ${fmt(cost)} caps to reset ${spent} attribute points.`, '');
256:     this.ui.render();
257:     this.saveNow();
258:   }
259: 
260:   openPerks() {
261:     const s = this.state;
262:     const points = s.perkPoints || 0;
263:     if (points < 1) {
264:       const owned = PERKS.filter((p) => perkRank(s, p.id) > 0);
265:       const chips = owned.map((p) => `<span class="perk-chip">${p.name} ×${perkRank(s, p.id)}</span>`).join('');
266:       this.ui.openModal({
267:         eyebrow: 'SURVIVOR PERKS',
268:         title: 'Perk ledger',
269:         body: `
270:           <p>You earn <strong>1 perk choice every 3 levels</strong>. You have <strong>${points}</strong> unspent.</p>
271:           ${owned.length ? `<div class="perk-owned">${chips}</div>` : '<p>No perks chosen yet.</p>'}
272:           <p>Cut down more of the wasteland to earn the next choice.</p>`,
273:         actions: [{ label: 'CLOSE', kind: '' }],
274:       });
275:       return;
276:     }
277:     const available = PERKS.filter((p) => perkRank(s, p.id) < p.max);
278:     if (!available.length) {
279:       this.ui.openModal({
280:         eyebrow: 'SURVIVOR PERKS',
281:         title: 'Every perk mastered',
282:         body: '<p>You have learned every trick the wastes can teach.</p>',
283:         actions: [{ label: 'CLOSE', kind: '' }],
284:       });
285:       return;
286:     }
287:     const pool = [...available].sort(() => Math.random() - 0.5).slice(0, 3);
288:     const body = `
289:       <p>Choose 1 of 3. ${points} choice${points > 1 ? 's' : ''} available.</p>
290:       <div class="perk-choice">
291:         ${pool.map((p) => `
292:           <div class="perk-option">
293:             <strong>${p.name}<span>RANK ${perkRank(s, p.id)}/${p.max}</span></strong>
294:             <span>${p.desc}</span>
295:           </div>`).join('')}
296:       </div>
297:       <p>Perks are permanent for this survivor, even through a core overload.</p>`;
298:     this.ui.openModal({
299:       eyebrow: 'SURVIVOR PERKS',
300:       title: 'Choose a perk',
301:       body,
302:       actions: pool.map((p) => ({
303:         label: `TAKE ${p.name.toUpperCase()}`,
304:         kind: '',
305:         onClick: () => this.choosePerk(p.id),
306:       })),
307:     });
308:   }
309: 
310:   choosePerk(id) {
311:     const s = this.state;
312:     const perk = PERKS.find((p) => p.id === id);
313:     if (!perk || (s.perkPoints || 0) < 1) return;
314:     const rank = perkRank(s, id);
315:     if (rank >= perk.max) {
316:       this.ui.toast(`${perk.name} is already maxed.`, 'bad');
317:       return;
318:     }
319:     s.perks[id] = rank + 1;
320:     s.perkPoints -= 1;
321:     this.audio.levelUp();
322:     this.ui.toast(`PERK ACQUIRED · ${perk.name} ×${rank + 1}`, 'lore');
323:     this.log(`${perk.name} rank ${rank + 1} learned. ${perk.desc}`, 'lore');
324:     this.ui.render();
325:     this.saveNow();
326:   }
327: 
328:   buyOutfit(index) {
329:     const s = this.state;
330:     const outfit = OUTFITS[index];
331:     if (!outfit) return;
332:     const lvl = outfitLevel(s, outfit.id);
333:     if (lvl >= outfit.max) {
334:       this.ui.toast(`${outfit.name} is already max tier.`, 'bad');
335:       return;
336:     }
337:     const cost = outfitCost(outfit, lvl);
338:     if (!canAfford(s, cost)) return this.deny(cost);
339:     const before = playerStats(s);
340:     spend(s, cost);
341:     s.outfits[outfit.id] = lvl + 1;
342:     const after = playerStats(s);
343:     s.combat.hp = Math.min(after.maxHp, s.combat.hp + Math.max(0, after.maxHp - before.maxHp));
344:     this.audio.buy();
345:     const verb = lvl === 0 ? 'Crafted' : 'Upgraded';
346:     this.ui.toast(`${verb} ${outfit.name} · Lv.${lvl + 1}`, 'good');
347:     this.log(`${outfit.name} Lv.${lvl + 1} equipped. ${outfit.effect(lvl + 1)}.`, 'good');
348:     if (outfit.id === 'rebreather' && lvl === 0) this.ui.toast('Rebreather online — better crits and XP gain.', 'good');
349:     this.ui.render();
350:     this.saveNow();
351:   }
352: 
353:   selectLayer(index) {
354:     const s = this.state;
355:     if (index < 0 || index >= LAYERS.length) return;
356:     if (index < s.layersUnlocked) {
357:       if (s.layer !== index) {
358:         s.layer = index;
359:         this.log(`Descended to ${LAYERS[index].name}.`, '');
360:         this.ui.render();
361:       }
362:       return;
363:     }
364:     if (index !== s.layersUnlocked) {
365:       this.ui.toast('Open the earlier shafts first.', 'bad');
366:       this.audio.error();
367:       return;
368:     }
369:     const layer = LAYERS[index];
370:     const req = layer.unlock;
371:     if (s.pickaxe < req.pickaxe) {
372:       this.ui.toast(`Requires pickaxe Lv.${req.pickaxe}. You have Lv.${s.pickaxe}.`, 'bad');
373:       this.audio.error();
374:       return;
375:     }
376:     if (!canAfford(s, req.ore)) {
377:       this.ui.toast(`Need ${costLabel(req.ore)} to break through.`, 'bad');
378:       this.audio.error();
379:       return;
380:     }
381:     spend(s, req.ore);
382:     s.layersUnlocked = index + 1;
383:     s.layer = index;
384:     this.audio.buy();
385:     this.ui.toast(`NEW SHAFT · ${layer.name}`, 'good');
386:     this.log(`${layer.name} opened at ${layer.depth}m. ${layer.blurb}`, 'good');
387:     this.ui.render();
388:     this.saveNow();
389:   }
390: 
391:   buyPickaxe() {
392:     const s = this.state;
393:     const cost = pickaxeCost(s.pickaxe);
394:     if (!canAfford(s, cost)) return this.deny(cost);
395:     spend(s, cost);
396:     s.pickaxe += 1;
397:     this.audio.buy();
398:     this.log(`Tool tuning raised to Lv.${s.pickaxe}. Vein damage ${fmt(pickPower(s), 1)}.`, 'good');
399:     if (s.pickaxe === 3) this.ui.toast('Tool tuning Lv.3 — Rust Flats can be opened.', 'good');
400:     this.ui.render();
401:     this.saveNow();
402:   }
403: 
404:   buyCrew() {
405:     const s = this.state;
406:     const cost = crewCost(s.crew);
407:     if (!canAfford(s, cost)) return this.deny(cost);
408:     spend(s, cost);
409:     s.crew += 1;
410:     this.audio.buy();
411:     this.ui.toast(`Survivor ${s.crew} joined · ore yield +${s.crew * 8}%`, 'good');
412:     this.log(`Crew expanded to ${s.crew}. Every ore source is ${s.crew * 8}% richer.`, 'good');
413:     this.ui.render();
414:     this.saveNow();
415:   }
416: 
417:   buyDrill(index) {
418:     const s = this.state;
419:     if (index < 0 || index >= s.layersUnlocked) {
420:       this.ui.toast('That shaft is not open yet.', 'bad');
421:       this.audio.error();
422:       return;
423:     }
424:     const cost = drillCost(index, s.drills[index] || 0);
425:     if (!canAfford(s, cost)) return this.deny(cost);
426:     spend(s, cost);
427:     s.drills[index] = (s.drills[index] || 0) + 1;
428:     this.audio.buy();
429:     const layer = LAYERS[index];
430:     this.log(`Drill rig ${s.drills[index]} online in ${layer.name} · +${fmt(drillRate(s, index), 2)} ${ORES[layer.ore].name}/s.`, 'good');
431:     this.ui.render();
432:     this.saveNow();
433:   }
434: 
435:   buyWeapon() {
436:     const s = this.state;
437:     const cost = weaponCost(s.combat.gear.weapon);
438:     if (!canAfford(s, cost)) return this.deny(cost);
439:     spend(s, cost);
440:     s.combat.gear.weapon += 1;
441:     this.audio.buy();
442:     const stats = playerStats(s);
443:     this.log(`${combatWeapon(s).name} tuned to Lv.${s.combat.gear.weapon}. Attack ${fmt(stats.attack, 1)}.`, 'good');
444:     this.ui.render();
445:     this.saveNow();
446:   }
447: 
448:   buyArmor() {
449:     const s = this.state;
450:     const cost = armorCost(s.combat.gear.armor);
451:     if (!canAfford(s, cost)) return this.deny(cost);
452:     const oldMax = playerStats(s).maxHp;
453:     spend(s, cost);
454:     s.combat.gear.armor += 1;
455:     const stats = playerStats(s);
456:     s.combat.hp = Math.min(stats.maxHp, s.combat.hp + (stats.maxHp - oldMax));
457:     this.audio.buy();
458:     this.log(`Rad plate fitted. HP ${fmt(stats.maxHp)} · ${Math.round(stats.defense * 100)}% resist.`, 'good');
459:     this.ui.render();
460:     this.saveNow();
461:   }
462: 
463:   buyStim() {
464:     const s = this.state;
465:     if (s.combat.gear.stim >= STIM_MAX) {
466:       this.ui.toast('Stim kit is already at max tier.', 'bad');
467:       return;
468:     }
469:     const cost = stimCost(s.combat.gear.stim);
470:     if (!canAfford(s, cost)) return this.deny(cost);
471:     spend(s, cost);
472:     s.combat.gear.stim += 1;
473:     this.audio.buy();
474:     const stats = playerStats(s);
475:     this.ui.toast(`Stim kit built · +${stats.healPerKill} HP per kill`, 'good');
476:     this.log(`Stim kit rebuilt. Heals ${stats.healPerKill} HP after each kill; reboot time ${stats.deathMs / 1000}s.`, 'good');
477:     this.ui.render();
478:     this.saveNow();
479:   }
480: 
481:   equipTool(id) {
482:     const s = this.state;
483:     const tool = MINING_TOOLS.find((t) => t.id === id);
484:     if (!tool) return;
485:     if (!s.tools[tool.id]) {
486:       const cost = tool.unlock || {};
487:       if (!canAfford(s, cost)) return this.deny(cost);
488:       spend(s, cost);
489:       s.tools[tool.id] = true;
490:       this.audio.buy();
491:       this.ui.toast(`SCHEMATIC RECOVERED · ${tool.name}`, 'lore');
492:       this.log(`${tool.name} built from salvage. ${tool.stats}.`, 'good');
493:     } else if (s.equippedTool === tool.id && !s.loadout.tool) {
494:       return;
495:     }
496:     s.equippedTool = tool.id;
497:     s.loadout.tool = null;
498:     this.audio.tone({ freq: 360, end: 520, dur: 0.08, type: 'triangle', vol: 0.16 });
499:     this.ui.toast(`${tool.name} equipped`, 'good');
500:     this.ui.render();
501:     this.saveNow();
502:   }
503: 
504:   equipWeapon(id) {
505:     const s = this.state;
506:     const weapon = COMBAT_WEAPONS.find((w) => w.id === id);
507:     if (!weapon) return;
508:     if (!s.weapons[weapon.id]) {
509:       const cost = weapon.unlock || {};
510:       if (!canAfford(s, cost)) return this.deny(cost);
511:       spend(s, cost);
512:       s.weapons[weapon.id] = true;
513:       this.audio.buy();
514:       this.ui.toast(`SCHEMATIC RECOVERED · ${weapon.name}`, 'lore');
515:       this.log(`${weapon.name} built from salvage. ${weapon.stats}.`, 'good');
516:     } else if (s.equippedWeapon === weapon.id && !s.loadout.weapon) {
517:       return;
518:     }
519:     s.equippedWeapon = weapon.id;
520:     s.loadout.weapon = null;
521:     this.audio.tone({ freq: 300, end: 180, dur: 0.1, type: 'sawtooth', vol: 0.14 });
522:     this.ui.toast(`${weapon.name} equipped`, 'good');
523:     this.ui.render();
