527:   /* ── loot & loadout ──────────────────────────────────────── */
528:   addLoot(item) {
529:     const s = this.state;
530:     if (!item) return false;
531:     if ((s.inventory || []).length >= MAX_INVENTORY) {
532:       const value = scrapValue(item);
533:       s.caps += value;
534:       s.stats.totalCaps = (s.stats.totalCaps || 0) + value;
535:       this.ui.toast(`PACK FULL · ${item.name} auto-scrapped +${fmt(value)} caps`, 'bad');
536:       return false;
