/* Minimal CDP driver: launch chromium headless, connect, capture console + errors, run evals. */
import { spawn } from 'node:child_process';
import { mkdtempSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import path from 'node:path';

const CHROME = '/usr/bin/chromium';

export async function launch(url) {
  const dir = mkdtempSync(path.join(tmpdir(), 'chrome-prof-'));
  const proc = spawn(CHROME, [
    '--headless=new',
    '--no-sandbox',
    '--disable-gpu',
    '--disable-dev-shm-usage',
    '--remote-debugging-port=0',
    `--user-data-dir=${dir}`,
    '--window-size=1280,900',
    url,
  ], { stdio: ['ignore', 'pipe', 'pipe'] });

  const wsUrl = await new Promise((resolve, reject) => {
    let buf = '';
    const onData = (d) => {
      buf += d;
      const m = buf.match(/ws:\/\/[^\s]+/);
      if (m) resolve(m[0]);
    };
    proc.stderr.on('data', onData);
    proc.stdout.on('data', onData);
    setTimeout(() => reject(new Error('no ws url\n' + buf)), 15000);
  });

  const ws = new WebSocket(wsUrl);
  await new Promise((res, rej) => { ws.onopen = res; ws.onerror = rej; });

  let msgId = 0;
  const pending = new Map();
  const events = [];
  const consoleMsgs = [];
  ws.onmessage = (ev) => {
    const msg = JSON.parse(ev.data);
    if (msg.id && pending.has(msg.id)) {
      const { resolve, reject } = pending.get(msg.id);
      pending.delete(msg.id);
      if (msg.error) reject(new Error(JSON.stringify(msg.error)));
      else resolve(msg.result);
    } else if (msg.method) {
      events.push(msg);
      if (msg.method === 'Runtime.consoleAPICalled') {
        const text = (msg.params.args || []).map((a) => a.value ?? a.description ?? '').join(' ');
        consoleMsgs.push({ type: msg.params.type, text });
      } else if (msg.method === 'Runtime.exceptionThrown') {
        const d = msg.params.exceptionDetails;
        consoleMsgs.push({ type: 'EXCEPTION', text: d.exception?.description || d.text });
      } else if (msg.method === 'Log.entryAdded') {
        consoleMsgs.push({ type: 'LOG-' + msg.params.entry.level, text: msg.params.entry.text });
      }
    }
  };

  async function send(method, params = {}) {
    const id = ++msgId;
    ws.send(JSON.stringify({ id, method, params }));
    return new Promise((resolve, reject) => pending.set(id, { resolve, reject }));
  }

  await send('Runtime.enable');
  await send('Page.enable');
  await send('Runtime.evaluate', { expression: '1' }).catch(() => {});
  return {
    proc, ws, send, events, consoleMsgs,
    async eval(expr) {
      const r = await send('Runtime.evaluate', { expression: expr, awaitPromise: true, returnByValue: true });
      if (r.exceptionDetails) throw new Error('eval failed: ' + (r.exceptionDetails.exception?.description || r.exceptionDetails.text));
      return r.result.value;
    },
    close() {
      try { proc.kill('SIGKILL'); } catch {}
      try { ws.close(); } catch {}
    },
  };
}

export async function sleep(ms) { return new Promise((r) => setTimeout(r, ms)); }

export function fmtErrors(msgs) {
  return msgs.filter((m) => m.type === 'EXCEPTION' || m.type === 'error' || m.type === 'LOG-error' || m.type === 'LOG-severe' || (m.type === 'warning' && m.text.includes('Failed to load')))
    .map((m) => `[${m.type}] ${m.text}`).join('\n');
}

import { launch, sleep, fmtErrors } from './cdp.js';

const URL = 'http://localhost:3002/index.html';

const session = await launch(URL);
try {
  // Wait for game boot
  await sleep(2500);
  const boot = await session.eval(`({
    hasGame: !!window.game,
    hasState: window.game ? JSON.stringify(Object.keys(game.state).slice(0, 20)) : null,
    layer: game?.state?.layer,
    zones: game?.state?.combat?.unlocked,
    caps: game?.state?.caps,
    tab: document.getElementById('app')?.dataset.tab,
    resources: document.getElementById('resources')?.children?.length,
  })`);
  console.log('BOOT:', JSON.stringify(boot));

  // Basic interactions
  const r1 = await session.eval(`(function(){
    game.strikeMine(false, performance.now() + 100000); // bypass cd by setting lastStrike... actually calls with cd check
    return { scrap: game.state.ores.scrap, rendered: document.getElementById('pickPower')?.textContent };
  })()`);
  console.log('STRIKE:', JSON.stringify(r1));

  await sleep(2200);

  // Fast-forward progression: give resources, buy things, fight
  const r2 = await session.eval(`(function(){
    const s = game.state;
    Object.assign(s.ores, { scrap: 5000, iron: 2000, copper: 800, titanium: 300, uranium: 100, void: 0 });
    s.caps = 50000;
    game.buyPickaxe(); game.buyCrew();
    return { pick: s.pickaxe, crew: s.caps, caps: s.caps };
  })()`);
  console.log('BUY:', JSON.stringify(r2));

  // attack in combat
  const r3 = await session.eval(`(function(){
    game.attack(performance.now());
    return { enemyHp: game.state.combat.enemy && Math.round(game.state.combat.enemy.hp), auto: game.state.combat.auto };
  })()`);
  console.log('ATTACK:', JSON.stringify(r3));

  // tab switching
  await session.eval(`document.querySelector('.tab[data-tab="forge"]').click();`);
  await sleep(900);
  const forgeCards = await session.eval(`document.querySelectorAll('#toolCards .tool-card, #toolCards > *').length + '/' + document.querySelectorAll('#gearCards > *').length + '/' + document.querySelectorAll('#drillList > *').length`);
  console.log('FORGE CARDS:', forgeCards);

  await session.eval(`document.querySelector('.tab[data-tab="fight"]').click();`);
  await sleep(900);
  const fightCards = await session.eval(`document.querySelectorAll('#zoneList > *').length`);
  console.log('ZONE CARDS:', fightCards);

  // Let auto combat run a while
  await sleep(4000);
  const combatState = await session.eval(`({
    wave: game.state.combat.waves[game.state.combat.zone],
    kills: game.state.stats.kills,
    enemy: game.state.combat.enemy?.name,
    playerHp: Math.round(game.state.combat.hp),
    dead: game.state.combat.deadUntil > 0,
  })`);
  console.log('COMBAT:', JSON.stringify(combatState));

  // Deep check: layer unlock progression
  const r4 = await session.eval(`(function(){
    const s = game.state;
    s.pickaxe = 3;
    game.selectLayer(1);
    return { layersUnlocked: s.layersUnlocked, layer: s.layer };
  })()`);
  console.log('LAYER UNLOCK:', JSON.stringify(r4));

  // Gear / loot
  const gear = await session.eval(`(function(){
    game.salvageRun();
    return { inv: game.state.inventory.length, gearBtnCount: document.getElementById('gearBtn') ? 1 : 0 };
  })()`);
  console.log('SALVAGE:', JSON.stringify(gear));

  // Open loadout modal
  await session.eval(`document.getElementById('gearBtn').click()`);
  await sleep(600);
  const modalOpen = await session.eval(`!document.getElementById('modal').hidden + ':' + (document.getElementById('modalBody')?.children?.length || 0)`);
  console.log('GEAR MODAL:', modalOpen);
  await session.eval(`window.game.ui.closeModal()`);

  // Perk modal
  await session.eval(`game.openPerks()`);
  await sleep(400);
  const perkModal = await session.eval(`document.getElementById('modalTitle')?.textContent`);
  console.log('PERK MODAL:', perkModal);
  const r5 = await session.eval(`(function(){
    game.ui.closeModal();
    game.spendPoint('str');
    return { points: game.state.points, str: game.state.attributes.str };
  })()`);
  console.log('SPENDPOINT:', JSON.stringify(r5));

  // Persistence round-trip
  const saved = await session.eval(`localStorage.getItem('ashfall.save.v1') ? 'saved len ' + localStorage.getItem('ashfall.save.v1').length : 'NONE'`);
  console.log('SAVE:', saved);

  await sleep(1500);
} finally {
  const errs = fmtErrors(session.consoleMsgs);
  console.log('ERRORS:', errs || '(none)');
  session.close();
}

