178:   const elapsed = Math.max(0, Math.min(8 * 3600, (now - (state.lastSeen || now)) / 1000));
179:   if (elapsed < 60) return null;
180:   const gains = {};
181:   let total = 0;
182:   LAYERS.forEach((layer, i) => {
183:     const count = state.drills[i] || 0;
184:     if (!count) return;
185:     const amount = count * drillRate(state, i) * elapsed * 0.5;
186:     if (amount <= 0) return;
187:     gains[layer.ore] = (gains[layer.ore] || 0) + amount;
188:     state.ores[layer.ore] += amount;
189:     state.stats.totalMined += amount;
190:     total += amount;
191:   });
192:   const capRate = salvageCapsRate(state);
193:   const caps = capRate > 0 ? capRate * elapsed * 0.5 : 0;
194:   if (caps > 0) {
195:     state.caps += caps;
196:     state.stats.totalCaps = (state.stats.totalCaps || 0) + caps;
197:   }
198:   const stats = playerStats(state);
199:   state.combat.hp = Math.min(stats.maxHp, state.combat.hp + stats.maxHp * 0.01 * elapsed);
200:   if (state.combat.deadUntil < now) state.combat.deadUntil = 0;
201:   if (total <= 0 && caps <= 0) return null;
202:   return { seconds: elapsed, gains, total, caps };
203: }
