import { launch, sleep, fmtErrors } from './cdp.js';

const URL = 'http://localhost:3002/index.html';
const out = [];
const say = (k, v) => { out.push(k + ': ' + JSON.stringify(v)); };

const session = await launch(URL);
try {
  await sleep(2200);
  // Prime the save: wipe localStorage for deterministic start
  await session.eval(`localStorage.clear(); location.reload();`);
  await sleep(2500);

  // ── 1. keyboard bindings ──
  const kb = await session.eval(`(async function(){
    const fire = (key) => window.dispatchEvent(new KeyboardEvent('keydown', { key }));
    const press = (el, key="", type="keydown") => el.dispatchEvent(new KeyboardEvent(type, { key: "" }));
    const before = game.state.ores.scrap;
    const scene = document.getElementById('mineScene');
    scene.dispatchEvent(new MouseEvent('click', { bubbles: true }));
    await new Promise(r => setTimeout(r, 300));
    return { scrapAfterClick: game.state.ores.scrap >= before, strikeBtn: !!document.getElementById('strikeBtn') };
  })()`);
  say('KB-CLICK', kb);

  // ── 2. rush progression to final zone ──
  const rush = await session.eval(`(function(){
    const s = game.state;
    s.caps = 5e6;
    Object.assign(s.ores, {
      scrap: 9e6, iron: 9e6, copper: 9e6, titanium: 9e6, uranium: 9e6, singularity: 9e6 });
    // secure all zones
    for (let i = 1; i < 6; i++) game.selectZone(i);
    // open all layers
    s.pickaxe = 5;
    for (let i = 1; i < 5; i++) game.selectLayer(i);
    // tier 10 combat gear
    while (s.combat.gear.weapon < 12) { s.combat.gear.weapon += 1; }
    while (s.combat.gear.armor < 12) { s.combat.gear.armor += 1; }
    while (s.combat.gear.stim < 10) { s.combat.gear.stim += 1; }
    return {
      zones: s.combat.unlocked, zone: s.combat.zone,
      layers: s.layersUnlocked, layer: s.layer,
      atk: Math.round(game.playerStats ? 0 : 0)|| Math.round(require0())|| undefined,
    };
  })()`);
  say('RUSH', rush);

  // playerStats check
  const ps = await session.eval(`(function(){
    const s = game.state;
    const st = window.__ps && window.__ps(s);
    return true;
  })()`).catch(e => e.message);
  // (playerStats is module private; use game internals instead)
  const ps2 = await session.eval(`(function(){
    const s = game.state;
    // use ui rendering to expose stats
    return {
      atkShown: document.getElementById('atkStat') ? document.getElementById('atkStat').textContent : null,
      hpShown: document.getElementById('playerHpText') ? document.getElementById('playerHpText').textContent : null,
      gear: s.combat.gear,
    };
  })()`);
  say('STATS', ps2);

  // ── 3. fast kill loop to wave 20 boss (Warden Prime in final zone?) ──
  // final zone index 5; set zone 5, waves[5]=19 then kill to hit boss wave 20
  const arena = await session.eval(`(function(){
    const s = game.state;
    s.combat.zone = 5;
    s.combat.waves[5] = 19;
    game.combatRenderer.enemyKey = '';
    s.combat.enemy = null;
    return true;
  })()`);
  // let combat run until boss spawns and dies
  let bossSeen = false, primeKillsAfter = 0;
  for (let i = 0; i < 40; i++) {
    await sleep(500);
    const st = await session.eval(`({
      name: game.state.combat.enemy && game.state.combat.enemy.name,
      boss: !!(game.state.combat.enemy && game.state.combat.enemy.boss),
      hp: game.state.combat.enemy && Math.max(0, Math.round(game.state.combat.enemy.hp)),
      wave: game.state.combat.waves[5],
      prime: game.state.combat.primeKills,
      dead: game.state.combat.deadUntil > 0,
    })`);
    if (st.boss) bossSeen = true;
    if (st.prime > 0 || st.wave >= 21) { primeKillsAfter = st.prime; break; }
    if (i === 39) primeKillsAfter = st.prime;
  }
  say('BOSS-FIGHT', { bossSeen, primeKillsAfter });

  // ── 4. overload / prestige ──
  const ov = await session.eval(`(function(){
    // Give primeKills for the gain calc, then overload via the real path
    game.state.combat.primeKills = Math.max(game.state.combat.primeKills, 1);
    const gainBefore = 1 + game.state.combat.primeKills * 2;
    game.confirmOverload();
    const modalOpen = !document.getElementById('modal').hidden;
    // click DETONATE button
    const btns = [...document.querySelectorAll('#modalActions button')];
    const detonate = btns.find(b => /DETONATE/.test(b.textContent));
    if (detonate) detonate.click();
    return {
      modalOpen, gain: gainBefore,
      afterShards: game.state.shards,
      afterCaps: game.state.caps,
      afterLevel: game.state.level,
      afterZone: game.state.combat.unlocked,
      afterInventory: (game.state.inventory || []).length,
    };
  })()`);
  say('OVERLOAD', ov);

  // victory modal shown?
  const vic = await session.eval(`({
    title: document.getElementById('modalTitle').textContent,
    hidden: document.getElementById('modal').hidden,
  })`);
  say('VICTORY', vic);
  const closeVic = await session.eval(`(function(){
    const btns = [...document.querySelectorAll('#modalActions button')];
    btns.forEach(b => b.click());
    return document.getElementById('modal').hidden;
  })()`);
  say('VICTORY-CLOSE', closeVic);

  // ── 5. outfits to max tier ──
  const outfits = await session.eval(`(function(){
    const s = game.state;
    ['rebreather','duster','charm'].forEach(id => { s.outfits[id] = 0; });
    game.buyOutfit(0); // costs caps
    return { rebreather: s.outfits.rebreather, caps: Math.round(s.caps) };
  })()`);
  say('OUTFIT', outfits);

  // ── 6. equip/salvage cycle on loot items ──
  const loot = await session.eval(`(function(){
    const s = game.state;
    s.inventory = [];
    const ids = [];
    for (let i = 0; i < 4; i++) {
      const it = window.__mk && window.__mk(s);
      void it; void ids;
    }
    game.salvageRun();
    return { inv: s.inventory.length };
  })()`);
  say('SALVAGE-RUN', loot);

  // equip + scrap through UI modal
  const gearFlow = await session.eval(`(function(){
    game.ui.openGear();
    const id = game.state.inventory[0] && game.state.inventory[0].id;
    if (id) game.equipLoot(id);
    return { equipped: id ? game.state.loadout : null };
  })()`);
  say('GEAR-EQUIP', gearFlow);

  // ── 7. persist + reload round-trip ──
  const preState = await session.eval(`(function(){
    game.saveNow();
    const s = game.state;
    return { shards: s.shards, level: s.level, points: s.points, out1: s.outfits.rebreather, inv: s.inventory.length, detonations: s.stats.detonations };
  })()`);
  say('PRE-RELOAD', preState);
  await session.eval(`location.reload();`);
  await sleep(2500);
  const post = await session.eval(`({
    hasGame: !!window.game,
    shards: game && game.state.shards,
    level: game && game.state.level,
    points: game && game.state.points,
    out1: game && game.state.outfits.rebreather,
    inv: game && game.state.inventory.length,
    detonations: game && game.state.stats.detonations,
    stateOk: game && JSON.stringify(Object.keys(game.state.combat)).length > 5,
  })`);
  say('POST-RELOAD', post);

  // ── 8. offline report path ──
  const offline = await session.eval(`(function(){
    const s = game.state;
    s.drills = [2, 1, 0, 0, 0];
    s.lastSeen = Date.now() - 300000; // 5 min
    game.saveNow();
    return { drills: s.drills, lastSeen: s.lastSeen };
  })()`);
  await session.eval(`location.reload();`);
  await sleep(2500);
  const offlineModal = await session.eval(`({
    title: document.getElementById('modalTitle').textContent,
    hasGame: !!window.game,
  })`);
  say('OFFLINE-RELOAD', { ...offline, ...offlineModal });
  await session.eval(`[...document.querySelectorAll('#modalActions button')].forEach(b => b.click())`);

  // ── 9. mobile tab bar behavior + full swap of all interactions via UI buttons ──
  const uiBtns = await session.eval(`(async function(){
    const clickIds = ['strikeBtn','autoMineBtn','attackBtn','autoBtn','perkBtn','respecBtn','overloadBtn','salvageRunBtn','resetBtn','soundBtn'];
    const results = {};
    for (const id of clickIds) {
      const el = document.getElementById(id);
      if (!el) { results[id] = 'missing'; continue; }
      if (id === 'resetBtn') continue; // skip confirming wipe
      el.click();
      results[id] = 'ok';
      await new Promise(r => setTimeout(r, 100));
    }
    return results;
  })()`);
  say('UI-BUTTONS', uiBtns);

  // close any modal from those clicks, then confirm tab switching works for all tabs
  const tabs = await session.eval(`(async function(){
    const res = {};
    for (const t of ['mine','forge','fight']) {
      const tab = document.querySelector('.tab[data-tab="' + t + '"]');
      tab.click();
      await new Promise(r => setTimeout(r, 150));
      res[t] = document.getElementById('app').dataset.tab;
    }
    return res;
  })()`);
  say('TABS', tabs);

  // ── 10. tick for a few seconds with everything maxed, watch for NaN corruption ──
  const nan = await session.eval(`(function(){
    const bad = (v) => Number.isNaN(v) || !isFinite(v);
    const s = game.state;
    const vals = [s.caps, s.shards, s.level, s.xp, s.combat.hp,
      ...Object.values(s.ores), ...s.drills, ...s.combat.waves];
    return { allFinite: !vals.some(bad), caps: Math.round(s.caps), hp: Math.round(s.combat.hp) };
  })()`);
  say('NAN-CHECK', nan);

  await sleep(2000);
} finally {
  const errs = fmtErrors(session.consoleMsgs);
  console.log('ERRORS:', errs || '(none)');
  console.log(out.join('\n'));
  session.close();
}

