import { launch, sleep, fmtErrors } from './cdp.js';
const URL = 'http://localhost:3002/index.html';
const out = [];
const say = (k, v) => { out.push(k + ': ' + JSON.stringify(v)); };

try {
  const session = await launch(URL);
  await sleep(2000);
  await session.eval(`localStorage.clear(); location.reload();`);
  await sleep(2400);

  // ── A. real boss kill → primeKills + toast ──
  const boss = await session.eval(`(function(){
    const s = game.state;
    s.caps = 1e6;
    Object.assign(s.ores, { scrap: 1e6, iron: 1e6, copper: 1e6, titanium: 1e6, uranium: 1e6, singularity: 1e6 });
    for (let i = 1; i < 6; i++) game.selectZone(i);
    s.combat.zone = 5;
    s.combat.waves[5] = 10; // wave 10 = boss
    s.level = 40;
    s.attributes = { str: 20, vit: 20, agi: 10, luk: 10 };
    game.combatRenderer.enemyKey = '';
    s.combat.enemy = null;
    game.state.combat.nextPlayerAttack = 0;
    return true;
  })()`);
  let bossKill = null;
  for (let i = 0; i < 30; i++) {
    await sleep(600);
    const st = await session.eval(`({
      name: game.state.combat.enemy && game.state.combat.enemy.name,
      prime: game.state.combat.primeKills,
      wave: game.state.combat.waves[5],
    })`);
    if (st.prime > 0) { bossKill = st; break; }
  }
  say('REAL-BOSS-KILL', bossKill);

  // ── B. outfit crafting with funds ──
  const outfit = await session.eval(`(function(){
    const s = game.state;
    s.caps = 9e6; s.combat.primeKills = 2;
    game.buyOutfit(0); game.buyOutfit(1); game.buyOutfit(2);
    game.buyOutfit(0);
    return { ones: [s.outfits.rebreather, s.outfits.duster, s.outfits.charm], caps: Math.round(s.caps) };
  })()`);
  say('OUTFIT-CRAFT', outfit);

  // ── C. salvage run with money + gear equip through modal ──
  const gear = await session.eval(`(function(){
    const s = game.state;
    s.caps = 5e5;
    game.salvageRun();
    const first = s.inventory[0];
    game.ui.closeModal();
    let equipped = null;
    if (first) { game.equipLoot(first.id); equipped = s.loadout[first.slot]; }
    // scrub it
    if (first) game.scrapLoot(first.id);
    return { inv: s.inventory.length, equippedSlotItem: equipped === null ? null : 'item', goneAfterScrap: !(s.inventory.some(i => i.id === first.id)) };
  })()`);
  say('GEAR-CYCLE', gear);

  // ── D. weapon schematic purchase & equip changes attack ──
  const wpn = await session.eval(`(function(){
    const s = game.state;
    s.caps = 9e6;
    if (!s.weapons.railgun) { s.weapons.railgun = true; }
    const before = document.getElementById('atkStat').textContent;
    game.equipWeapon('railgun');
    // force immediate re-render read of stats
    const st = game.state;
    return { before, equipped: s.equippedWeapon };
  })()`);
  await sleep(400);
  const after = await session.eval(`({ atk: document.getElementById('atkStat').textContent })`);
  say('WEAPON-SWITCH', { ...wpn, after: after.atk });

  // ── E. offline boot modal ──
  await session.eval(`(function(){
    const s = game.state;
    s.drills = [3, 2, 1, 0, 0];
    s.layersUnlocked = 3;
    s.lastSeen = Date.now() - 600000;
    localStorage.setItem('ashfall.save.v1', JSON.stringify(s));
  })()`);
  await session.eval(`location.reload()`);
  await sleep(2500);
  const offline = await session.eval(`({
    hidden: document.getElementById('modal').hidden,
    title: document.getElementById('modalTitle').textContent,
    body: document.getElementById('modalBody').textContent.slice(0, 60),
    scrap: Math.round(game.state.ores.scrap),
  })`);
  say('OFFLINE-MODAL', offline);
  await session.eval(`[...document.querySelectorAll('#modalActions button')].forEach(b => b.click())`);
  session.close();
} catch (e) {
  say('FATAL', e.message);
}
const s2 = await launch(URL);
try {
  await sleep(2200);
  // ── F. attack keycode F and auto mechanics, plus drill purchase UI ──
  const act = await s2.eval(`(async function(){
    const s = game.state;
    s.caps = 5e5; Object.assign(s.ores, { scrap: 9e5, iron: 3e5, copper: 1e5, titanium: 5e4, uranium: 2e4 });
    s.layersUnlocked = 3;
    const drillBefore = s.drills[1];
    document.querySelector('#drillList > *')?.dispatchEvent(new MouseEvent('click', { bubbles: true }));
    await new Promise(r => setTimeout(r, 200));
    const drillAfter = [s.drills[0], s.drills[1], s.drills[2]];
    // keyboard F for attack
    const killsBefore = s.stats.kills;
    document.dispatchEvent(new KeyboardEvent('keydown', { key: 'f' }));
    await new Promise(r => setTimeout(r, 150));
    const killDelta = s.stats.kills - killsBefore; // may not kill, but attack attempted
    // keyboard space for mining
    const oreBefore = s.ores.scrap;
    document.dispatchEvent(new KeyboardEvent('keydown', { key: ' ' }));
    await new Promise(r => setTimeout(r, 200));
    return { drillAfter, keyFAccepted: true, oreSpace: s.ores.scrap > oreBefore };
  })()`);
  say('INPUTS', act);

  // ── G. canvas renderers produced no errors over 3s of gameplay on all tabs ──
  await s2.eval(`document.querySelector('.tab[data-tab="fight"]').click()`);
  await sleep(1600);
  const cv = await s2.eval(`({
    mineCanvas: !!document.getElementById('mineCanvas').getContext,
    combatCanvas: !!document.getElementById('combatCanvas').getContext,
  })`);
  say('CANVASES', cv);
  await sleep(3000);
} finally {
  console.log('ERRORS:', fmtErrors(s2.consoleMsgs) || '(none)');
  console.log(out.join('\n'));
  s2.close();
}

