import { launch, sleep, fmtErrors } from './cdp.js';
const URL = 'http://localhost:3002/index.html';
const out = [];
const say = (k, v) => { out.push(k + ': ' + JSON.stringify(v)); };

{
  const session = await launch(URL);
  try {
    await sleep(2200);
    await session.eval(`localStorage.clear(); location.reload();`);
    await sleep(2400);

    // ── 1. reboot time is 5 s ──
    const death = await session.eval(`(function(){
      const s = game.state;
      s.stats.deaths = (s.stats.deaths || 999);
      game.playerDied(performance.now(), { deathMs: 5000 });
      return { deadUntil: s.combat.deadUntil > 0, banner: document.querySelector('.death-banner') !== null };
    })()`);
    // measure actual reboot duration
    const t0 = await session.eval(`(function(){
      const s = game.state;
      s.combat.deadUntil = performance.now() + 5000;
      return performance.now();
    })()`);
    let rebootObserved = null;
    for (let i = 0; i < 40; i++) {
      await sleep(250);
      const dead = await session.eval(`game.state.combat.deadUntil > 0`);
      if (!dead) { rebootObserved = performance.now(); break; }
    }
    // Use deadUntil span instead: set again and watch the interval logic restore
    const dt = await session.eval(`(function(){
      const s = game.state;
      s.combat.deadUntil = performance.now() + 5000;
      s.combat.enemy = null;
      return null;
    })()`);
    let restored = false;
    const tRebootStart = Date.now();
    for (let i = 0; i < 50; i++) {
      await sleep(150);
      const ok = await session.eval(`(function(){
        const c = game.state.combat;
        return c.deadUntil === 0 && !!c.enemy;
      })()`);
      if (ok) { restored = true; break; }
    }
    say('REBOOT-5S', { restoreTimeSec: restored && Math.round((Date.now() - tRebootStart) / 100)/10, restored });
    say('PLAYER-DIE-CALLED', death);

    // ── 2. loadout weapon drives the fighter: stats + FORGE marker ──
    const weaponLoadout = await session.eval(`(function(){
      const s = game.state;
      s.caps = 9e6;
      // unlock two schematics
      s.weapons = { pipeaxe: true, railgun: true };
      // craft a railgun-class loot weapon and a pipeaxe-class one
      const mk = (classId) => ({ id: 'w_'+classId, slot: 'weapon', rarity: 'rare', name: 'Test '+classId, level: 10, classId, stats: { damage: 0.1, crit: 0.02 } });
      const rail = mk('railgun'), axe = mk('pipeaxe');
      s.inventory.push(rail, axe);
      s.loadout.weapon = rail.id; // loot railgun in hand
      const atkLoadoutRail = Math.round(combatAtk());
      function combatAtk(){ return null; } // not reachable; fallback below
      return null;
    })()`);
    // step through states with renders between
    const seq = [];
    for (const state of ['railgunloot', 'pipeaxe-schematic', 'railgun-schematic', 'pipeaxe-loot']) {
      await session.eval(`(function(){
        const s = game.state;
        if ('${state}' === 'railgunloot') s.loadout.weapon = 'w_railgun';
        if ('${state}' === 'pipeaxe-loot') s.loadout.weapon = 'w_pipeaxe';
        if ('${state}' === 'pipeaxe-schematic') { game.equipWeapon('pipeaxe'); }
        if ('${state}' === 'railgun-schematic') { game.equipWeapon('railgun'); }
        game.ui.render();
      })()`);
      await sleep(250);
      seq.push(await session.eval(`(function(){
        const s = game.state;
        const vox = document.querySelector('.loadout-slot[data-slot="weapon"]');
        const marker = vox && vox.classList.contains('filled');
        return { state: '${state}', loadout: s.loadout.weapon, tuned: s.equippedWeapon,
                 summary: document.getElementById('weaponSummary').textContent };
      })()`) );
    }
    say('WEAPON-SWITCH-SEQ', seq);

    // actual visual: the drawn weapon changes. Export the active weapon key from render? Read canvas diff:
    // detect via attack interval shown AND FORGE marker
    const forgeMarker = await session.eval(`(function(){
      const s = game.state;
      game.equipWeapon('pipeaxe');
      const cards = [...document.querySelectorAll('#combatWeaponCards .tool-card')];
      return cards.length ? cards.map(c => c.className.includes('equipped') ? 1 : 0).join('') : 'no-elec-cards';
    })()`);
    say('FORGE-MARKERS(pipeaxe active among 12)', forgeMarker);

    // visual change: sample the combat canvas hash while holding pipeaxe vs railgun loot
    await session.eval(`document.querySelector('.tab[data-tab="fight"]').click()`);
    await sleep(700);
    const snap = async () => session.eval(`(function(){
      const c = document.getElementById('combatCanvas');
      const ctx = c.getContext('2d');
      const d = ctx.getImageData(c.width*0.45|0, c.height*0.55|0, 60, 40).data;
      let sum = 0; for (const v of d) sum += v;
      return sum;
    })()`);
    const h1 = await snap(); // currently whichever active

    // swap in the railgun loot weapon and resample
    await session.eval(`(function(){ const s = game.state; s.loadout.weapon = 'w_railgun'; game.ui.render(); })()`);
